    let reservationRequests = 0;
    const reservationKeys: string[] = [];
    const reservationBodies: string[] = [];
    let lostFirstResponse = false;
    let firstAttemptId: string | undefined;
    let replayObservation: ReplayObservation | undefined;
    let replayVisibleCopy: string[] = [];
    page.on('request', (requestEvent) => {
      if (requestEvent.method() === 'POST' && new URL(requestEvent.url()).pathname === '/api/bff/number-registrations') {
        reservationRequests += 1;
        reservationKeys.push(requestEvent.headers()['idempotency-key'] ?? '');
        reservationBodies.push(requestEvent.postData() ?? '');
      }
    });
    let authorizeRequests = 0;
    page.on('request', (requestEvent) => {
      if (requestEvent.method() === 'POST' && /\/number-registrations\/[^/]+\/authorize$/.test(new URL(requestEvent.url()).pathname)) authorizeRequests += 1;
