      if (route.request().method() !== 'POST') return route.continue();
      const realResponse = await route.fetch();
      const parsed = JSON.parse((await realResponse.body()).toString()) as Record<string, unknown>;
      const attempt = parsed.attempt && typeof parsed.attempt === 'object' ? parsed.attempt as Record<string, unknown> : null;
      if (!lostFirstResponse) {
        lostFirstResponse = true;
        firstAttemptId = typeof attempt?.id === 'string' ? attempt.id : undefined;
        await route.abort('failed');
        return;
      }
      replayObservation = {
        status: realResponse.status(),
        hasAttempt: Boolean(attempt),
        sameAttempt: typeof attempt?.id === 'string' && firstAttemptId ? attempt.id === firstAttemptId : null,
        hasNonce: typeof parsed.nonce === 'string' && parsed.nonce.length > 0,
        replay: parsed.replay === true,
        state: typeof attempt?.state === 'string' ? attempt.state : null,
        stage: typeof attempt?.stage === 'string' ? attempt.stage : null,
        version: typeof attempt?.version === 'number' ? attempt.version : null,
        errorCode: typeof parsed.code === 'string' && /^[A-Z0-9_]{1,80}$/.test(parsed.code) ? parsed.code : null,
      };
      await route.fulfill({ response: realResponse });
    });
    const before = await context.request.get(`${API}/api/bff/business-units`);
    expect(before.ok()).toBeTruthy();
    const beforeUnits = (await before.json() as UnitList).businessUnits.length;
