    await page.getByRole('button', { name: 'Reservar tentativa' }).click();
    await expect.poll(() => replayObservation !== undefined).toBe(true);
    expect(reservationKeys[1]).toBe(reservationKeys[0]);
    expect(reservationBodies[1]).toBe(reservationBodies[0]);
    replayVisibleCopy = await page.locator('[role="alert"], [role="status"]').allTextContents();
    console.log('[REPLAY-EVIDENCE] ' + JSON.stringify({ ...replayObservation, visibleCopy: replayVisibleCopy }));
    expect(replayObservation).toMatchObject({ status: 201, hasAttempt: true, sameAttempt: true, hasNonce: true, replay: true, state: 'PENDING_AUTH' });
