    await page.evaluate(() => window.__oldNumberLoginCallback?.({ authResponse: { code: 'late-after-bu-switch' } }));
    await expect.poll(() => authorizeRequests).toBe(0);
    expect(reservationRequests).toBe(4);
    expect(reservationKeys[3]).toBeTruthy();
    expect(reservationKeys[3]).not.toBe(reservationKeys[2]);
    expect(reservationBodies[3]).not.toBe(reservationBodies[2]);
    const finalUnits = await context.request.get(`${API}/api/bff/business-units`);
    expect(finalUnits.ok()).toBeTruthy();
