  test('20 disparos repetidos em cinco reservas não duplicam uma intenção enquanto a resposta real está retida; resposta antiga não regride a etapa', async ({ page, request, context }) => {
    const seed = await newActor(request);
    await installSdkDouble(page);
    await signIn(context, page, seed.tenantA.owner);
    await page.getByRole('button', { name: 'Iniciar cadastro' }).click();
    await selectBu(page, seed.tenantA.buId);

    let activeWave = 0;
    const waveRequests = Array.from({ length: 5 }, () => 0);
    let inFlight = 0;
    let maximumInFlight = 0;
    const inFlightAtBarrier: number[] = [];
    let totalSubmitTriggers = 0;
    let staleStage: string | undefined;
    let staleResponseUrl: string | undefined;
    let staleResponseFinished = false;
    const releases: Array<() => void> = [];
    const barriers = Array.from({ length: 5 }, (_, index) => new Promise<void>((resolve) => { releases[index] = resolve; }));
    await page.route((url) => url.origin === new URL(page.url()).origin && url.pathname === '/api/bff/number-registrations', async (route) => {
      if (route.request().method() !== 'POST') return route.continue();
      const wave = activeWave;
      waveRequests[wave] += 1;
      const firstInWave = waveRequests[wave] === 1;
      const realResponse = await route.fetch();
      if (firstInWave) {
        inFlight += 1;
        maximumInFlight = Math.max(maximumInFlight, inFlight);
        try { await barriers[wave]; } finally { inFlight -= 1; }
      }
      await route.fulfill({ response: realResponse });
    });

    for (let wave = 0; wave < 5; wave += 1) {
      activeWave = wave;
      const submit = page.getByRole('button', { name: 'Reservar tentativa' });
      const form = await submit.evaluateHandle((button) => button.closest('form'));
      await submit.click();
      try {
        await expect.poll(() => waveRequests[wave]).toBe(1);
        await expect.poll(() => inFlight).toBe(1);
      inFlightAtBarrier.push(inFlight);
        await form.evaluate((element) => {
          if (!(element instanceof HTMLFormElement)) throw new Error('expected reservation form');
          for (let repeat = 0; repeat < 20; repeat += 1) element.dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));
        });
      totalSubmitTriggers += 20;
