import { describe, expect, it } from 'vitest';
import { TentativaNumero } from './cadastroNumero';
import { DonoCicloCadastro } from './cadastroNumero.lifecycle';

const attempt = (overrides: Partial<TentativaNumero> = {}): TentativaNumero => ({
  id: 'attempt-a', buId: 'bu-a', channelId: null, tipo: 'OFICIAL', operation: 'NOVO',
  state: 'PENDING_AUTH', stage: 'RESERVED', errorCode: null, expiresAt: '2026-10-15T00:00:00.000Z',
  version: 1, generation: 0, ...overrides,
});

describe('dono do ciclo de cadastro', () => {
  it('rejects delayed lower-version reads after an action and admits the action generation transition', () => {
    const owner = new DonoCicloCadastro();
    const reserve = owner.iniciar('reserva', null)!;
    expect(owner.reservar(attempt(), reserve)).toBe(true);
    owner.finalizar(reserve);

    const oldRead = owner.tokenLeitura()!;
    const confirm = owner.iniciar('confirmacao', 'attempt-a')!;
    const promoted = attempt({
      channelId: 'channel-a', state: 'PENDING_RECEIPT', stage: 'REGISTERED_PENDING_RECEIPT', version: 4, generation: 1,
    });
    expect(owner.aplicar(promoted, confirm, 'acao')).toBe(true);
    expect(owner.observar(attempt({ version: 2, state: 'PENDING_NUMBER', stage: 'AUTHORIZED' }), oldRead)).toBe(false);
    expect(owner.atual()).toEqual(promoted);
  });

  it('allows an explicit pair action to replace the selected BU attempt only after matching safe projection', () => {
    const owner = new DonoCicloCadastro();
    const reserve = owner.iniciar('reserva', null)!;
    expect(owner.reservar(attempt({ channelId: 'official-channel', state: 'PENDING_NUMBER' }), reserve)).toBe(true);
    owner.finalizar(reserve);
    const pair = owner.iniciarPareamento('bu-a', 'channel-a')!;
    const renewed = attempt({ id: 'attempt-b', channelId: 'channel-a', tipo: 'NAO_OFICIAL', operation: 'REAUTORIZAR', state: 'PENDING_NUMBER', stage: 'PAIRING', generation: 2, version: 1 });
    const correlation = { buId: 'bu-a', channelId: 'channel-a', attemptId: 'attempt-b', generation: 2 };
    expect(owner.adotarPareamento(renewed, pair, correlation, {
      buId: 'bu-a', channelId: 'channel-a', currentAttemptId: 'attempt-old', generation: 2,
    })).toBe(false);
    expect(owner.adotarPareamento(renewed, pair, correlation, {
      buId: 'bu-a', channelId: 'channel-a', currentAttemptId: 'attempt-b', generation: 2,
    })).toBe(true);
    expect(owner.atual()).toEqual(renewed);
  });

  it('admits authoritative pre-effects cancellation that releases the channel slot and rejects its stale read', () => {
    const owner = new DonoCicloCadastro();
    const reserve = owner.iniciar('reserva', null)!;
    const reserved = attempt({ channelId: 'channel-a', stage: 'RESERVED', version: 4, generation: 1 });
    expect(owner.reservar(reserved, reserve)).toBe(true);
    owner.finalizar(reserve);

    const staleRead = owner.tokenLeitura()!;
    const cancel = owner.iniciar('acao', reserved.id)!;
    const cancelled = attempt({ channelId: null, state: 'CANCELLED', stage: 'CANCELLED', version: 5, generation: 1 });
    expect(owner.aplicar(cancelled, cancel, 'acao')).toBe(true);
    owner.finalizar(cancel);
    expect(owner.observar(reserved, staleRead)).toBe(false);
    expect(owner.atual()).toEqual(cancelled);

    const staleAction = owner.iniciar('acao', cancelled.id)!;
    expect(owner.aplicar(attempt({ channelId: 'other-channel', state: 'CANCELLED', stage: 'CANCELLED', version: 6, generation: 1 }), staleAction, 'acao')).toBe(false);
  });

  it('keeps one operation owner and prevents a stale completion from releasing a newer lifecycle', () => {
    const owner = new DonoCicloCadastro();
    const first = owner.iniciar('autorizacao', null)!;
    expect(owner.iniciar('verificacao', null)).toBeNull();
    owner.invalidar();
    const second = owner.iniciar('reserva', null)!;
    expect(owner.finalizar(first)).toBe(false);
    expect(owner.possui(second)).toBe(true);
  });
});
