 24	  async resolve(channelId: string, purpose: 'send' | 'registration' | 'verify' = 'send'): Promise<ResolvedChannelCredential> {
 25	    const channel = await this.prisma.buChannel.findUnique({
 26	      where: { id: channelId }, include: { credential: true, providerIdentities: true },
 27	    });
 28	    if (!channel || (purpose !== 'verify' && (!channel.ownNumberVerified || channel.verifiedEpoch !== channel.pairingEpoch))) {
