 53	      providerResourceIdentityId: m.providerResourceIdentityId, channelId: m.channelId, generation: m.generation,
 54	      pairingEpoch: m.pairingEpoch, buId: m.buId, channelOrigin: m.canal, externalMessageId: m.externalId ?? '',
 55	      contact: m.contato, contactType: m.ehGrupo ? 'GRUPO' : 'PESSOA', displayName: m.nomeExibicao,
 56	      direction: m.direcao, messageType: m.tipo, content: m.conteudo, authorName: m.autorNome,
 57	    });
 58	    const { conversation: conversa, message: mensagem, creationWinner } = accepted;
 59	    if (creationWinner) {
 60	      this.realtime.publicarNaBu(m.buId, { tipo: 'mensagem', conversaId: conversa.id, contato: conversa.contact, direcao: m.direcao, canal: m.canal, naoLidas: conversa.unreadCount });
 61	      if (m.direcao === 'IN' && m.tipo === 'TEXTO' && m.conteudo?.trim()) {
 62	        await this.executarTypebot(m, m.conteudo.trim(), conversa.id, accepted.conversationCreated).catch(() => undefined);
 63	      }
 64	    }
 65	    return { conversa, mensagem, reabriu: accepted.reopened, creationWinner, reconciled: accepted.reconciled };
 66	  }
