 68	  private async executarTypebot(incoming: MensagemRecebida, texto: string, conversationId: string, conversationCreated: boolean): Promise<void> {
 69	    const { buId, contato } = incoming;
 70	    const bu = await this.prisma.businessUnit.findUnique({ where: { id: buId }, select: { mantenedoraId: true } });
 71	    if (!bu) return;
 72	    const gatilhos = await this.prisma.typebotTrigger.findMany({
 73	      where: { active: true, bot: { status: 'ATIVO', mantenedoraId: bu.mantenedoraId }, OR: [{ buId: null }, { buId }] },
 74	      include: { bot: true }, orderBy: { createdAt: 'asc' },
 75	    });
 76	    const normalized = texto.toLocaleLowerCase('pt-BR');
 77	    const gatilho = gatilhos.find((g) => gatilhoCombina(g.kind, g.value, normalized, conversationCreated));
 78	    if (!gatilho || !this.typebot.configurado()) return;
 79	    const channel = await this.prisma.buChannel.findUnique({ where: { id: incoming.channelId } });
 80	    if (!channel) return;
 81	    const scoped = await this.credentials.resolve(channel.id);
 82	    if (scoped.provider === 'OFICIAL' && (!scoped.phoneNumberId || !scoped.accessToken)) return;
 83	    if (scoped.provider === 'NAO_OFICIAL' && !scoped.evolutionInstanceName) return;
 84	    const botId = gatilho.bot.publishedTypebotId;
 85	    if (!botId) return;
 86	    const atual = await this.prisma.typebotSession.findUnique({ where: { botId_buId_contato: { botId: gatilho.botId, buId, contato } } });
 87	    if (atual && (atual.mantenedoraId !== bu.mantenedoraId || atual.buId !== buId || atual.botId !== gatilho.botId || gatilho.bot.mantenedoraId !== bu.mantenedoraId)) return;
 88	    const resposta = atual?.ativo ? await this.typebot.continuar(atual.sessionId, texto) : await this.typebot.iniciar(botId, contato, texto);
 89	    const sessionId = 'sessionId' in resposta && typeof resposta.sessionId === 'string' ? resposta.sessionId : null;
 90	    if (!atual && sessionId) await this.prisma.typebotSession.create({ data: { botId: gatilho.botId, mantenedoraId: gatilho.bot.mantenedoraId, buId, contato, sessionId } });
 91	    for (const mensagem of resposta.messages) {
 92	      const saida = textoDaRespostaTypebot(mensagem);
 93	      if (!saida) continue;
 94	      const externalId = scoped.provider === 'OFICIAL'
 95	        ? await this.meta.enviarTexto(scoped.phoneNumberId!, contato, saida, scoped.accessToken!)
 96	        : await this.evolution.enviarTexto(scoped.evolutionInstanceName!, contato, saida);
 97	      if (!externalId) {
 98	        await this.acceptance.recordAmbiguousOutbound({
 99	          providerResourceIdentityId: scoped.providerResourceIdentityId, channelId: scoped.channelId, generation: scoped.generation,
100	          pairingEpoch: scoped.pairingEpoch, buId, channelOrigin: scoped.provider, contact: contato, contactType: 'PESSOA',
101	          conversationId, direction: 'OUT', messageType: 'TEXTO', content: saida, authorName: 'Typebot', senderResult: true,
102	        });
103	        throw new Error('OUTBOUND_MESSAGE_ID_MISSING');
104	      }
105	      const accepted = await this.acceptance.accept({
106	        providerResourceIdentityId: scoped.providerResourceIdentityId, channelId: scoped.channelId, generation: scoped.generation,
107	        pairingEpoch: scoped.pairingEpoch, buId, channelOrigin: scoped.provider, externalMessageId: externalId,
108	        contact: contato, contactType: 'PESSOA', conversationId, direction: 'OUT', messageType: 'TEXTO', content: saida,
109	        authorName: 'Typebot', senderResult: true,
110	      });
111	      if (accepted.creationWinner) this.realtime.publicarNaBu(buId, { tipo: 'mensagem', conversaId: conversationId, contato, direcao: 'OUT', canal: scoped.provider, naoLidas: accepted.conversation.unreadCount });
112	    }
113	  }
114	
115	}
